    12	class ReservationService {
    13	    private final Database db;
    14	    private final Repository repository;
    15	
    16	    ReservationService(Database db, Repository repository) {
    17	        this.db = db;
    18	        this.repository = repository;
    19	    }
    20	
    21	    List<Room> rooms() {
    22	        return db.transaction(repository::rooms);
    23	    }
    24	
    25	    List<Message> messages() {
    26	        return db.transaction(repository::messages);
    27	    }
    28	
    29	    Reservation create(JsonNode body) {
    30	        int roomNumber = integer(body, "roomNumber");
    31	        String guestName = text(body, "guestName");
    32	        String guestEmail = text(body, "guestEmail");
    33	        Identification identification = IdentificationTypes.fromRequest(body);
    34	        LocalDate checkIn = date(body, "checkIn");
    35	        LocalDate checkOut = date(body, "checkOut");
    36	        int guests = integer(body, "guests");
    37	        RatePlan plan = ratePlan(body);
    38	        if (!checkOut.isAfter(checkIn)) {
    39	            throw ApiException.invalid("A saída deve ser depois da entrada.");
    40	        }
    41	        if (guests < 1) {
    42	            throw ApiException.invalid("É preciso ao menos um hóspede.");
    43	        }
    44	        return db.transaction(c -> {
    45	            Room room = repository.findRoomLocked(c, roomNumber).orElseThrow(
    46	                    () -> new ApiException(404, "ROOM_NOT_FOUND", "Quarto " + roomNumber + " não existe."));
    47	            if (guests > room.capacity()) {
    48	                throw new ApiException(422, "CAPACITY_EXCEEDED",
    49	                        "O quarto " + roomNumber + " comporta até " + room.capacity() + " pessoas.");
    50	            }
    51	            if (repository.isRoomBooked(c, roomNumber, checkIn, checkOut)) {
    52	                throw new ApiException(409, "ROOM_UNAVAILABLE",
    53	                        "O quarto " + roomNumber + " já está reservado em alguma dessas noites.");
    54	            }
    55	            Pricing pricing = Pricing.quote(room, checkIn, checkOut, plan);
    56	            BigDecimal zero = Money.round(BigDecimal.ZERO);
    57	            return repository.insert(c, new Reservation(0, room, guestName, guestEmail, identification,
    58	                    checkIn, checkOut, guests, plan, pricing, Status.PENDING, zero, null));
    59	        });
    60	    }
    61	
    62	    Reservation get(long id) {
    63	        return db.transaction(c -> repository.find(c, id).orElseThrow(() -> notFound(id)));
    64	    }
    65	
    66	    Reservation confirm(long id) {
    67	        return change(id, Reservation::confirm, ReservationService::sendConfirmationEmail);
    68	    }
    69	
    70	    Reservation cancel(long id) {
    71	        return change(id, Reservation::cancel, null);
    72	    }
    73	
    74	    Reservation checkIn(long id) {
    75	        return change(id, Reservation::doCheckIn, null);
    76	    }
    77	
    78	    Reservation checkOut(long id) {
    79	        return change(id, Reservation::doCheckOut, null);
    80	    }
    81	
    82	    /** Segunda via: só existe para reserva paga. */
    83	    Reservation paidReservation(long id) {
    84	        Reservation r = get(id);
    85	        requirePaid(r);
    86	        return r;
    87	    }
    88	
    89	    private interface AfterChange {
    90	        void run(Repository repository, Connection c, Reservation r) throws SQLException;
    91	    }
    92	
    93	    private Reservation change(long id, UnaryOperator<Reservation> transition, AfterChange after) {
    94	        return db.transaction(c -> {
    95	            Reservation changed = transition.apply(repository.findLocked(c, id).orElseThrow(() -> notFound(id)));
    96	            repository.saveState(c, changed);
    97	            if (after != null) {
    98	                after.run(repository, c, changed);
    99	            }
   100	            return changed;
   101	        });
   102	    }
   103	
   104	    private static void sendConfirmationEmail(Repository repository, Connection c, Reservation r)
   105	            throws SQLException {
   106	        String document = r.identification().type().document().render(r);
   107	        String body = "Olá, " + r.guestName() + "!\n\n"
   108	                + "Sua reserva na Pousada Maré Alta está confirmada. Estes são os dados dela:\n\n"
   109	                + document + "\n\n"
   110	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
   111	                + "Até breve!";
   112	        repository.saveMessage(c, "EMAIL", r.guestEmail(), "Reserva confirmada - Pousada Maré Alta", body);
   113	    }
   114	
   115	    private static void requirePaid(Reservation r) {
   116	        if (!r.status().isPaid()) {
   117	            throw ApiException.notAllowed("A reserva está " + r.status() + " e não tem documento.");
   118	        }
   119	    }
   120	
   121	    private static ApiException notFound(long id) {
   122	        return new ApiException(404, "RESERVATION_NOT_FOUND", "Reserva " + id + " não existe.");
   123	    }
   124	
   125	    private static JsonNode required(JsonNode body, String field) {
   126	        JsonNode node = body.get(field);
   127	        if (node == null || node.isNull()) {
   128	            throw ApiException.invalid("Campo obrigatório ausente: " + field);
   129	        }
   130	        return node;
   131	    }
   132	
   133	    private static int integer(JsonNode body, String field) {
   134	        JsonNode node = required(body, field);
   135	        if (!node.isIntegralNumber() || !node.canConvertToInt()) {
   136	            throw ApiException.invalid("Campo inválido: " + field);
   137	        }
   138	        return node.asInt();
   139	    }
   140	
   141	    private static String text(JsonNode body, String field) {
   142	        JsonNode node = required(body, field);
   143	        if (!node.isTextual() || node.asText().isBlank()) {
   144	            throw ApiException.invalid("Campo inválido: " + field);
   145	        }
   146	        return node.asText().trim();
   147	    }
   148	
   149	    private static LocalDate date(JsonNode body, String field) {
   150	        try {
   151	            return LocalDate.parse(text(body, field));
   152	        } catch (java.time.format.DateTimeParseException e) {
   153	            throw ApiException.invalid("Data inválida em " + field);
   154	        }
   155	    }
   156	
   157	    private static RatePlan ratePlan(JsonNode body) {
   158	        try {
   159	            return RatePlan.valueOf(text(body, "ratePlan"));
   160	        } catch (IllegalArgumentException e) {
   161	            throw ApiException.invalid("Plano de tarifa inválido.");
   162	        }
   163	    }
   164	}
