    18	        this.url = url;
    19	        this.user = user;
    20	        this.password = password;
    21	    }
    22	
    23	    <T> T transaction(Work<T> work) {
    24	        try (Connection c = connect()) {
    25	            c.setAutoCommit(false);
    26	            try {
    27	                T result = work.run(c);
    28	                c.commit();
    29	                return result;
    30	            } catch (Throwable e) {
    31	                c.rollback();
    32	                throw e;
    33	            }
    34	        } catch (SQLException e) {
    35	            throw new IllegalStateException(e);
    36	        }
    37	    }
    38	
    39	    /** Cria o que falta no banco e espera por ele se ainda estiver subindo. */
    40	    void initialize() {
    41	        SQLException last = null;
    42	        for (int attempt = 0; attempt < 30; attempt++) {
    43	            try (Connection c = connect(); Statement s = c.createStatement()) {
    44	                c.setAutoCommit(false);
    45	                s.execute("select pg_advisory_xact_lock(7070)");
    46	                s.execute("""
    47	                        create table if not exists rooms (
    48	                          number int primary key,
    49	                          type text not null,
    50	                          capacity int not null,
    51	                          nightly_rate numeric(12,2) not null)""");
    52	                s.execute("""
    53	                        create table if not exists reservations (
    54	                          id bigserial primary key,
    55	                          room_number int not null references rooms(number),
    56	                          guest_name text not null,
    57	                          guest_email text not null,
    58	                          id_type text not null,
    59	                          id_values text not null,
    60	                          check_in date not null,
    61	                          check_out date not null,
    62	                          guests int not null,
    63	                          rate_plan text not null,
    64	                          nights int not null,
    65	                          subtotal numeric(12,2) not null,
    66	                          discount numeric(12,2) not null,
    67	                          total numeric(12,2) not null,
    68	                          status text not null,
    69	                          amount_paid numeric(12,2) not null default 0,
    70	                          refund numeric(12,2))""");
    71	                s.execute("""
    72	                        create table if not exists messages (
    73	                          id bigserial primary key,
    74	                          channel text not null,
    75	                          recipient text not null,
    76	                          subject text not null,
    77	                          body text not null)""");
    78	                s.execute("""
    79	                        insert into rooms (number, type, capacity, nightly_rate) values
    80	                          (101, 'STANDARD', 2, 249.90), (102, 'STANDARD', 2, 249.90),
    81	                          (201, 'DELUXE', 3, 389.90), (202, 'DELUXE', 3, 389.90),
    82	                          (301, 'SUITE', 4, 579.90)
    83	                        on conflict (number) do nothing""");
    84	                c.commit();
    85	                return;
    86	            } catch (SQLException e) {
    87	                last = e;
    88	                try {
    89	                    Thread.sleep(1000);
    90	                } catch (InterruptedException ie) {
    91	                    Thread.currentThread().interrupt();
    92	                    break;
    93	                }
    94	            }
    95	        }
    96	        throw new IllegalStateException("Banco indisponível", last);
    97	    }
