     1	package pousada;
     2	
     3	import com.fasterxml.jackson.databind.JsonNode;
     4	
     5	import java.util.ArrayList;
     6	import java.util.LinkedHashMap;
     7	import java.util.List;
     8	import java.util.Map;
     9	
    10	/** Registro dos jeitos de identificação. Um novo jeito entra aqui, com o seu documento. */
    11	final class IdentificationTypes {
    12	    private static final List<IdentificationType> ALL = List.of(
    13	            new IdentificationType("CPF", List.of("guestCpf"), new CpfReceipt()),
    14	            new IdentificationType("CNPJ", List.of("companyCnpj", "companyName"), new LodgingInvoice()),
    15	            new IdentificationType("PASSPORT", List.of("guestPassport", "guestCountry"), new BookingReceipt()));
    16	
    17	    private IdentificationTypes() {
    18	    }
    19	
    20	    static List<String> allFields() {
    21	        List<String> fields = new ArrayList<>();
    22	        ALL.forEach(t -> fields.addAll(t.fields()));
    23	        return fields;
    24	    }
    25	
    26	    static IdentificationType byCode(String code) {
    27	        return ALL.stream().filter(t -> t.code().equals(code)).findFirst().orElseThrow();
    28	    }
    29	
    30	    static Identification fromRequest(JsonNode body) {
    31	        List<IdentificationType> used = new ArrayList<>();
    32	        for (IdentificationType type : ALL) {
    33	            if (type.fields().stream().anyMatch(f -> isPresent(body, f))) {
    34	                used.add(type);
    35	            }
    36	        }
    37	        if (used.size() != 1) {
    38	            throw ApiException.invalid("Informe a identificação de um só jeito: guestCpf, companyCnpj com "
    39	                    + "companyName, ou guestPassport com guestCountry.");
    40	        }
    41	        IdentificationType type = used.get(0);
    42	        Map<String, String> values = new LinkedHashMap<>();
    43	        for (String field : type.fields()) {
    44	            JsonNode node = body.get(field);
    45	            if (node == null || !node.isTextual() || node.asText().isBlank()) {
    46	                throw ApiException.invalid("Campo obrigatório ausente ou inválido: " + field);
    47	            }
    48	            values.put(field, node.asText().trim());
    49	        }
    50	        return new Identification(type, values);
    51	    }
    52	
    53	    private static boolean isPresent(JsonNode body, String field) {
    54	        JsonNode node = body.get(field);
    55	        return node != null && !node.isNull();
    56	    }
    57	}
