     1	package pousada;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	
     7	record Pricing(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {
     8	
     9	    static Pricing quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    10	        BigDecimal subtotal = Money.round(BigDecimal.ZERO);
    11	        int nights = 0;
    12	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    13	            subtotal = subtotal.add(nightPrice(room.nightlyRate(), night));
    14	            nights++;
    15	        }
    16	        BigDecimal discount = plan.discountOn(subtotal);
    17	        return new Pricing(nights, subtotal, discount, subtotal.subtract(discount));
    18	    }
    19	
    20	    static BigDecimal nightPrice(BigDecimal rate, LocalDate night) {
    21	        return isHighSeason(night) ? Money.percent(rate, "1.20") : Money.round(rate);
    22	    }
    23	
    24	    static boolean isHighSeason(LocalDate night) {
    25	        Month month = night.getMonth();
    26	        return month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY
    27	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    28	    }
    29	}
