    18	
    19	    String occupancy(String dateParam) {
    20	        LocalDate night;
    21	        try {
    22	            night = LocalDate.parse(dateParam);
    23	        } catch (DateTimeParseException | NullPointerException e) {
    24	            throw ApiException.invalid("Data inválida; use o formato 2027-07-10.");
    25	        }
    26	        return db.transaction(c -> {
    27	            List<Reservation> occupied = repository.paidOccupying(c, night);
    28	            int totalRooms = repository.rooms(c).size();
    29	            StringBuilder csv = new StringBuilder("room,type,reservation,check_in,check_out\n");
    30	            for (Reservation r : occupied) {
    31	                csv.append(r.room().number()).append(',').append(r.room().type()).append(',')
    32	                        .append(r.id()).append(',').append(r.checkIn()).append(',').append(r.checkOut())
    33	                        .append('\n');
    34	            }
    35	            return csv.append("total,").append(occupied.size()).append('/').append(totalRooms).append('\n')
    36	                    .toString();
    37	        });
    38	    }
    39	
    40	    String revenue(String monthParam) {
    41	        YearMonth month;
    42	        try {
    43	            month = YearMonth.parse(monthParam);
    44	        } catch (DateTimeParseException | NullPointerException e) {
    45	            throw ApiException.invalid("Mês inválido; use o formato 2027-07.");
    46	        }
    47	        return db.transaction(c -> {
    48	            List<Reservation> list = repository.startingBetween(c, month.atDay(1), month.atEndOfMonth());
    49	            StringBuilder csv = new StringBuilder("reservation,room,check_in,check_out,status,amount\n");
    50	            BigDecimal sum = Money.round(BigDecimal.ZERO);
    51	            for (Reservation r : list) {
    52	                csv.append(r.id()).append(',').append(r.room().number()).append(',').append(r.checkIn())
    53	                        .append(',').append(r.checkOut()).append(',').append(r.status()).append(',')
    54	                        .append(r.retained().toPlainString()).append('\n');
    55	                sum = sum.add(r.retained());
    56	            }
    57	            return csv.append("total,").append(sum.toPlainString()).append('\n').toString();
    58	        });
    59	    }
    60	}
