     1	package pousada;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	
     6	record Reservation(long id, Room room, String guestName, String guestEmail, Identification identification,
     7	                   LocalDate checkIn, LocalDate checkOut, int guests, RatePlan ratePlan, Pricing pricing,
     8	                   Status status, BigDecimal amountPaid, BigDecimal refund) {
     9	
    10	    Reservation confirm() {
    11	        requireStatus("confirmada", Status.PENDING);
    12	        return withStatus(Status.CONFIRMED, pricing.total(), refund);
    13	    }
    14	
    15	    Reservation doCheckIn() {
    16	        requireStatus("com check-in", Status.CONFIRMED);
    17	        return withStatus(Status.CHECKED_IN, amountPaid, refund);
    18	    }
    19	
    20	    Reservation doCheckOut() {
    21	        requireStatus("com check-out", Status.CHECKED_IN);
    22	        return withStatus(Status.CHECKED_OUT, amountPaid, refund);
    23	    }
    24	
    25	    Reservation cancel() {
    26	        requireStatus("cancelada", Status.PENDING, Status.CONFIRMED);
    27	        return withStatus(Status.CANCELLED, amountPaid, ratePlan.refundFor(amountPaid));
    28	    }
    29	
    30	    BigDecimal retained() {
    31	        return amountPaid.subtract(refund == null ? BigDecimal.ZERO : refund);
    32	    }
    33	
    34	    private void requireStatus(String action, Status... allowed) {
    35	        for (Status s : allowed) {
    36	            if (status == s) {
    37	                return;
    38	            }
    39	        }
    40	        throw ApiException.notAllowed("A reserva está " + status + " e não pode ficar " + action + ".");
    41	    }
    42	
    43	    private Reservation withStatus(Status newStatus, BigDecimal paid, BigDecimal newRefund) {
    44	        return new Reservation(id, room, guestName, guestEmail, identification, checkIn, checkOut, guests,
    45	                ratePlan, pricing, newStatus, paid, newRefund);
    46	    }
    47	}
